"""Read the arc line detections generated by fridadrp-find_arc_lines from a FITS file"""

from astropy.io import fits
from astropy.table import Table

from fridadrp.core import FRIDA_NSLICES


def check_is_a_valid_arc_lines_file(hdul):
    """Check if the input FITS file is a valid arc lines file

    The file must have been generated by fridadrp-find_arc_lines: the
    primary header contains KEYCODE='ARC_LINES', and there is one table
    extension SLCNUMnn (nn = slice number, 1-based) for each processed
    slice. Slices that were not processed have no extension.

    Parameters
    ----------
    hdul : astropy.io.fits.HDUList
        HDUList object containing the FITS file to be checked.

    Raises
    ------
    ValueError
        If the input FITS file is not a valid arc lines file.
    """
    list_required_keywords = ["KEYCODE", "UUID", "IMAGE"]
    for keyword in list_required_keywords:
        if keyword not in hdul[0].header:
            raise ValueError(f"Input file does not contain a {keyword} header keyword.")
    expected_keycode_values = ["ARC_LINES"]
    if hdul[0].header["KEYCODE"] not in expected_keycode_values:
        raise ValueError(
            f"Invalid KEYCODE={hdul[0].header['KEYCODE']}.\nExpected value is one of {expected_keycode_values}."
        )
    list_extnames = [f"SLCNUM{i:02d}" for i in range(1, FRIDA_NSLICES + 1) if f"SLCNUM{i:02d}" in hdul]
    if len(list_extnames) == 0:
        raise ValueError("Input file does not contain any SLCNUMnn extension.")
    list_required_columns = ["row_index", "x_peak"]
    for extname in list_extnames:
        if not isinstance(hdul[extname], fits.BinTableHDU):
            raise ValueError(f"Extension {extname} is not a binary table.")
        for colname in list_required_columns:
            if colname not in hdul[extname].columns.names:
                raise ValueError(f"Extension {extname} does not contain a {colname} column.")


def read_arc_lines(input_arc_lines):
    """Read the arc line detections from a FITS file

    The positions of the arc lines are given as 0-based array indices:
    column 'row_index' along NAXIS2 and column 'x_peak' along NAXIS1.

    Parameters
    ----------
    input_arc_lines : str
        Path to the FITS file generated by fridadrp-find_arc_lines.

    Returns
    -------
    list_arc_line_tables : list of astropy.table.Table or None
        List of FRIDA_NSLICES elements (index = slice index, 0-based),
        with the table of arc line detections of each slice. The element
        is None if the slice was not processed (no extension in the file),
        and an empty table if the slice was processed without detections.

    Raises
    ------
    ValueError
        If the input FITS file is not a valid arc lines file.
    """

    with fits.open(input_arc_lines) as hdul:
        check_is_a_valid_arc_lines_file(hdul)

        list_arc_line_tables = [None] * FRIDA_NSLICES
        for islice in range(FRIDA_NSLICES):
            extname = f"SLCNUM{islice + 1:02d}"
            if extname in hdul:
                list_arc_line_tables[islice] = Table.read(hdul[extname])

    return list_arc_line_tables
